export function apiRateLimit(enabled: boolean) {
  if (!enabled) {
    return { limit: 0, reason: "Disabled" };
  }
  return { limit: 100 };
}

export function jobRateLimit(enabled: boolean) {
  if (!enabled) {
    return { limit: 0, reason: "Disabled" };
  }
  return { limit: 100 };
}
